import * as THREE from './three.module.js';
const canvas=document.querySelector('#world');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let renderer;try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});}catch(e){document.querySelector('#fallback').hidden=false;}
if(renderer) init();
function init(){
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
const scene=new THREE.Scene();scene.background=new THREE.Color('#e9e1f3');scene.fog=new THREE.Fog('#e9e1f3',19,48);
const camera=new THREE.PerspectiveCamera(34,innerWidth/innerHeight,.1,100);camera.position.set(0,2,15);camera.lookAt(0,0,0);
const envCanvas=document.createElement('canvas');envCanvas.width=1024;envCanvas.height=512;const ctx=envCanvas.getContext('2d');let grad=ctx.createLinearGradient(0,0,1024,512);grad.addColorStop(0,'#faf5ff');grad.addColorStop(.22,'#b3d7fb');grad.addColorStop(.4,'#65608a');grad.addColorStop(.5,'#f9d2d5');grad.addColorStop(.68,'#f7f4e8');grad.addColorStop(.8,'#aca1dc');grad.addColorStop(1,'#ededff');ctx.fillStyle=grad;ctx.fillRect(0,0,1024,512);ctx.fillStyle='#ffffff';ctx.fillRect(70,60,180,180);ctx.fillRect(600,40,70,260);ctx.fillStyle='#2b204d';ctx.fillRect(380,0,25,512);const env=new THREE.CanvasTexture(envCanvas);env.mapping=THREE.EquirectangularReflectionMapping;const pmrem=new THREE.PMREMGenerator(renderer);scene.environment=pmrem.fromEquirectangular(env).texture;
scene.add(new THREE.HemisphereLight(0xffffff,0xb3a0c8,2.3));const light=new THREE.DirectionalLight(0xfff6f1,4);light.position.set(-3,8,7);light.castShadow=true;light.shadow.mapSize.set(1024,1024);light.shadow.camera.left=-10;light.shadow.camera.right=10;light.shadow.camera.top=10;light.shadow.camera.bottom=-10;light.shadow.normalBias=.04;scene.add(light);const rim=new THREE.PointLight(0xc0abff,65);rim.position.set(6,3,-3);scene.add(rim);
const stage=new THREE.Group();stage.position.set(3.1,-.1,0);scene.add(stage);
const material=new THREE.MeshPhysicalMaterial({color:0xd9b9eb,metalness:.78,roughness:.18,clearcoat:1,clearcoatRoughness:.1,iridescence:1,iridescenceIOR:1.65,iridescenceThicknessRange:[100,500]});
const sculpture=new THREE.Group();stage.add(sculpture);
const knot=new THREE.Mesh(new THREE.TorusKnotGeometry(1.36,.48,240,40,2,3),material);knot.rotation.set(.25,.15,-.42);knot.castShadow=true;sculpture.add(knot);
const whiteMat=new THREE.MeshPhysicalMaterial({color:0xf6e5d4,metalness:.22,roughness:.25,clearcoat:1});
const platform=new THREE.Mesh(new THREE.CylinderGeometry(2.45,2.45,.13,96),new THREE.MeshStandardMaterial({color:0xdbd0ed,roughness:.36,metalness:.2}));platform.position.y=-2.43;platform.receiveShadow=true;stage.add(platform);
const rimDisk=new THREE.Mesh(new THREE.TorusGeometry(2.44,.025,8,96),new THREE.MeshStandardMaterial({color:0xf4ecff,metalness:.45,roughness:.2}));rimDisk.rotation.x=Math.PI/2;rimDisk.position.y=-2.35;stage.add(rimDisk);
const orbit=new THREE.Mesh(new THREE.TorusGeometry(2.65,.012,8,160),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.65}));orbit.rotation.set(1.12,.25,.25);stage.add(orbit);
const satellites=[];const colors=[0xffc99c,0xc6b4f3,0xe7a9d1,0xb6dcd0,0xd7e8f7];
for(let i=0;i<8;i++){const mat=i===0?whiteMat:new THREE.MeshPhysicalMaterial({color:colors[i%5],metalness:i%2?.38:.12,roughness:.2,clearcoat:1});const mesh=new THREE.Mesh(new THREE.SphereGeometry(i===0?.48:.12+Math.random()*.2,36,24),mat);mesh.castShadow=true;stage.add(mesh);satellites.push({mesh,angle:i/8*Math.PI*2,radius:2.6+Math.random()*.6,y:(Math.random()-.5)*3,speed:.12+Math.random()*.14});}
const ring=new THREE.Mesh(new THREE.TorusGeometry(.37,.12,24,64),new THREE.MeshPhysicalMaterial({color:0xf2b7d2,metalness:.4,roughness:.18,clearcoat:1}));ring.position.set(-2.5,1.7,.5);ring.rotation.set(.4,.5,-.5);stage.add(ring);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(180,180),new THREE.MeshStandardMaterial({color:0xe6ddf0,roughness:.85}));floor.rotation.x=-Math.PI/2;floor.position.y=-2.75;floor.receiveShadow=true;scene.add(floor);
const grid=new THREE.GridHelper(120,100,0xc6b7d8,0xc6b7d8);grid.position.y=-2.74;grid.material.transparent=true;grid.material.opacity=.22;scene.add(grid);
const starGeo=new THREE.BufferGeometry();const starPos=new Float32Array(180*3);for(let i=0;i<180;i++){starPos[i*3]=(Math.random()-.5)*35;starPos[i*3+1]=(Math.random()-.4)*20;starPos[i*3+2]=-Math.random()*18;}starGeo.setAttribute('position',new THREE.BufferAttribute(starPos,3));const dust=new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xffffff,size:.035,transparent:true,opacity:.75}));scene.add(dust);
const bursts=[];const burstGeo=new THREE.IcosahedronGeometry(.055,0);const burstMats=colors.map(color=>new THREE.MeshStandardMaterial({color,metalness:.4,roughness:.3}));let burstPower=0;
let mood='daydream',energy=.45,paused=reduced,elapsed=0,last=performance.now(),drag=false,moved=false,previousX=0,previousY=0,rotateX=0,rotateY=0,targetX=0,targetY=0;
const palettes={daydream:{bg:'#e9e1f3',floor:'#e6ddf0',body:0xd9b9eb,platform:0xdbd0ed},afterglow:{bg:'#f4d5c3',floor:'#edcbbd',body:0xf7ae94,platform:0xe9bcae},cosmic:{bg:'#17182f',floor:'#24233f',body:0x9b8cec,platform:0x4a416c}};let palette=palettes.daydream;
function resize(){const w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();if(w<760){camera.position.set(0,2,20);stage.position.set(1,-1.1,0);stage.scale.setScalar(.83);}else{camera.position.set(0,2,15);stage.position.set(w<1100?2.7:3.1,-.1,0);stage.scale.setScalar(1);}camera.lookAt(0,0,0);}window.addEventListener('resize',resize);resize();
canvas.addEventListener('pointerdown',e=>{drag=true;moved=false;previousX=e.clientX;previousY=e.clientY;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-previousX,dy=e.clientY-previousY;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;targetY+=dx*.008;targetX+=dy*.008;previousX=e.clientX;previousY=e.clientY;}});canvas.addEventListener('pointerup',()=>{drag=false;if(!moved)burst();});canvas.addEventListener('pointercancel',()=>drag=false);
let toastTimer;function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300);}
function burst(){burstPower=1;for(let i=0;i<(reduced?14:70);i++){const mesh=new THREE.Mesh(burstGeo,burstMats[i%5]);mesh.position.copy(stage.position);mesh.position.y+=.4;const velocity=new THREE.Vector3((Math.random()-.5)*8,(Math.random()-.3)*7,(Math.random()-.5)*7);scene.add(mesh);bursts.push({mesh,velocity,life:2.2});}playChime();}
document.querySelector('#hit').addEventListener('click',()=>{burst();toast(['A tiny celebration. Just for you.','You’re doing great. Keep floating.','Permission to do absolutely nothing.','More of this feeling, please.'][Math.floor(Math.random()*4)]);});
document.querySelectorAll('.mood').forEach(button=>button.addEventListener('click',()=>{mood=button.dataset.mood;palette=palettes[mood];document.body.classList.toggle('cosmic',mood==='cosmic');document.querySelectorAll('.mood').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});playChime();if(audio)updateDrone();}));
document.querySelector('#energy').addEventListener('input',e=>{energy=Number(e.target.value)/100;document.querySelector('#energy-label').textContent=energy<.3?'Soft & slow':energy<.7?'A little floaty':'Beautiful chaos';});
const pause=document.querySelector('#pause');function updatePause(){pause.textContent=paused?'▷':'Ⅱ';pause.setAttribute('aria-label',paused?'Resume animation':'Pause animation');pause.setAttribute('aria-pressed',String(paused));}updatePause();pause.addEventListener('click',()=>{paused=!paused;updatePause();});
document.querySelector('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Your world is already as wide as it can be.');}});document.addEventListener('fullscreenchange',()=>{document.querySelector('#fullscreen').innerHTML=document.fullscreenElement?'LEAVE IMMERSION <span>⤡</span>':'GO FULL IMMERSION <span>⤢</span>';});
let audio,master,drone=[],soundOn=false;const notes={daydream:[130.81,164.81,196],afterglow:[146.83,185,220],cosmic:[110,130.81,164.81]};function updateDrone(){drone.forEach((o,i)=>o.frequency.setTargetAtTime(notes[mood][i],audio.currentTime,.6));}function playChime(){if(!soundOn)return;notes[mood].forEach((freq,i)=>{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=freq*4;gain.gain.setValueAtTime(0,audio.currentTime);gain.gain.linearRampToValueAtTime(.1,audio.currentTime+.02+i*.09);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+1.8+i*.09);osc.connect(gain).connect(master);osc.start(audio.currentTime+i*.09);osc.stop(audio.currentTime+2.2);});}
document.querySelector('#sound').addEventListener('click',async()=>{try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=0;master.connect(audio.destination);notes[mood].forEach(freq=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.value=.065;o.connect(g).connect(master);o.start();drone.push(o);});}await audio.resume();soundOn=!soundOn;master.gain.setTargetAtTime(soundOn?.5:0,audio.currentTime,.3);document.querySelector('#sound').setAttribute('aria-pressed',String(soundOn));document.querySelector('#sound-label').textContent=soundOn?'Sound on':'Sound off';if(soundOn)playChime();}catch{toast('Sound isn’t available in this browser.');}});
const bgColor=new THREE.Color(),floorColor=new THREE.Color(),bodyColor=new THREE.Color(),platformColor=new THREE.Color();
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05);last=now;if(document.hidden)return;if(!paused)elapsed+=dt*(.25+energy*1.8);rotateX+=(targetX-rotateX)*.07;rotateY+=(targetY-rotateY)*.07;sculpture.rotation.set(rotateX+Math.sin(elapsed*.4)*.12,rotateY+elapsed*.13,Math.sin(elapsed*.3)*.07);sculpture.position.y=Math.sin(elapsed*.8)*.18;sculpture.scale.setScalar(1+burstPower*.13);burstPower=Math.max(0,burstPower-dt*1.5);satellites.forEach((s,i)=>{const a=s.angle+elapsed*s.speed;s.mesh.position.set(Math.cos(a)*s.radius,s.y+Math.sin(elapsed+i)*.22,Math.sin(a)*1.3);});ring.rotation.y=elapsed*.25;ring.position.y=1.6+Math.sin(elapsed)*.15;dust.rotation.y=elapsed*.009;scene.background.lerp(bgColor.set(palette.bg),.035);scene.fog.color.copy(scene.background);floor.material.color.lerp(floorColor.set(palette.floor),.035);material.color.lerp(bodyColor.set(palette.body),.035);platform.material.color.lerp(platformColor.set(palette.platform),.035);for(let i=bursts.length-1;i>=0;i--){const b=bursts[i];b.life-=dt;b.mesh.position.addScaledVector(b.velocity,dt);b.velocity.y-=dt*1.5;b.mesh.rotation.x+=dt*2;b.mesh.scale.setScalar(Math.min(1,b.life));if(b.life<=0){scene.remove(b.mesh);bursts.splice(i,1);}}renderer.render(scene,camera);}requestAnimationFrame(frame);
}
